<parameter name="contents">import express from 'express';
import bcrypt from 'bcryptjs';
import rateLimit from 'express-rate-limit';
import { v4 as uuidv4 } from 'uuid';
import Database from 'better-sqlite3';
import path from 'path';
import { fileURLToPath } from 'url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const db = new Database(path.join(__dirname, 'auth.db'));
const app = express();

app.use(express.json());

// Initialize database schema
db.exec(`
  CREATE TABLE IF NOT EXISTS users (
    id TEXT PRIMARY KEY,
    email TEXT UNIQUE NOT NULL,
    password_hash TEXT NOT NULL,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );

  CREATE TABLE IF NOT EXISTS sessions (
    id TEXT PRIMARY KEY,
    user_id TEXT NOT NULL,
    expires_at DATETIME NOT NULL,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (user_id) REFERENCES users(id)
  );

  CREATE TABLE IF NOT EXISTS login_attempts (
    id TEXT PRIMARY KEY,
    email TEXT NOT NULL,
    ip_address TEXT NOT NULL,
    attempted_at DATETIME DEFAULT CURRENT_TIMESTAMP
  );

  CREATE INDEX IF NOT EXISTS idx_sessions_user_id ON sessions(user_id);
  CREATE INDEX IF NOT EXISTS idx_sessions_expires_at ON sessions(expires_at);
  CREATE INDEX IF NOT EXISTS idx_login_attempts_email_ip ON login_attempts(email, ip_address);
`);

// Rate limiting: max 5 failed login attempts per email per 15 minutes
const loginLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  keyGenerator: (req) => req.body.email || req.ip,
  skip: (req) => req.method !== 'POST',
  handler: (req, res) => {
    res.status(429).json({ error: 'Too many login attempts. Try again in 15 minutes.' });
  }
});

// Helper: Get client IP
function getClientIp(req) {
  return req.ip || req.connection.remoteAddress || 'unknown';
}

// Helper: Record failed login attempt
function recordFailedAttempt(email, ip) {
  const stmt = db.prepare('INSERT INTO login_attempts (id, email, ip_address) VALUES (?, ?, ?)');
  stmt.run(uuidv4(), email, ip);
}

// Helper: Check if IP is rate limited for email
function isRateLimited(email, ip) {
  const fifteenMinutesAgo = new Date(Date.now() - 15 * 60 * 1000);
  const stmt = db.prepare(`
    SELECT COUNT(*) as count FROM login_attempts 
    WHERE email = ? AND ip_address = ? AND attempted_at > ?
  `);
  const result = stmt.get(email, ip, fifteenMinutesAgo.toISOString());
  return result.count >= 5;
}

// Helper: Create session
function createSession(userId) {
  const sessionId = uuidv4();
  const expiresAt = new Date(Date.now() + 24 * 60 * 60 * 1000); // 24 hours

  const stmt = db.prepare(`
    INSERT INTO sessions (id, user_id, expires_at) 
    VALUES (?, ?, ?)
  `);
  stmt.run(sessionId, userId, expiresAt.toISOString());

  return { sessionId, expiresAt };
}

// Helper: Verify session
function verifySession(sessionId) {
  const stmt = db.prepare(`
    SELECT user_id FROM sessions 
    WHERE id = ? AND expires_at > datetime('now')
  `);
  return stmt.get(sessionId);
}

// Middleware: Require authentication
function requireAuth(req, res, next) {
  const sessionId = req.headers.authorization?.split(' ')[1];

  if (!sessionId) {
    return res.status(401).json({ error: 'Missing session token' });
  }

  const session = verifySession(sessionId);
  if (!session) {
    return res.status(401).json({ error: 'Invalid or expired session' });
  }

  req.userId = session.user_id;
  next();
}

// Signup endpoint
app.post('/signup', async (req, res) => {
  const { email, password } = req.body;

  if (!email || !password) {
    return res.status(400).json({ error: 'Email and password required' });
  }

  if (password.length < 8) {
    return res.status(400).json({ error: 'Password must be at least 8 characters' });
  }

  try {
    const passwordHash = await bcrypt.hash(password, 10);
    const userId = uuidv4();

    const stmt = db.prepare(`
      INSERT INTO users (id, email, password_hash) 
      VALUES (?, ?, ?)
    `);
    stmt.run(userId, email, passwordHash);

    const { sessionId, expiresAt } = createSession(userId);

    res.status(201).json({
      message: 'Account created successfully',
      sessionToken: sessionId,
      expiresAt
    });
  } catch (err) {
    if (err.message.includes('UNIQUE constraint failed')) {
      return res.status(409).json({ error: 'Email already registered' });
    }
    res.status(500).json({ error: 'Signup failed' });
  }
});

// Login endpoint
app.post('/login', loginLimiter, async (req, res) => {
  const { email, password } = req.body;
  const ip = getClientIp(req);

  if (!email || !password) {
    return res.status(400).json({ error: 'Email and password required' });
  }

  if (isRateLimited(email, ip)) {
    return res.status(429).json({ error: 'Too many failed attempts. Try again in 15 minutes.' });
  }

  try {
    const stmt = db.prepare('SELECT id, password_hash FROM users WHERE email = ?');
    const user = stmt.get(email);

    if (!user) {
      recordFailedAttempt(email, ip);
      return res.status(401).json({ error: 'Invalid email or password' });
    }

    const isValid = await bcrypt.compare(password, user.password_hash);

    if (!isValid) {
      recordFailedAttempt(email, ip);
      return res.status(401).json({ error: 'Invalid email or password' });
    }

    const { sessionId, expiresAt } = createSession(user.id);

    res.json({
      message: 'Login successful',
      sessionToken: sessionId,
      expiresAt
    });
  } catch (err) {
    res.status(500).json({ error: 'Login failed' });
  }
});

// Protected endpoint (example)
app.get('/profile', requireAuth, (req, res) => {
  const stmt = db.prepare('SELECT id, email, created_at FROM users WHERE id = ?');
  const user = stmt.get(req.userId);

  res.json({ user });
});

// Logout endpoint
app.post('/logout', requireAuth, (req, res) => {
  const sessionId = req.headers.authorization?.split(' ')[1];
  const stmt = db.prepare('DELETE FROM sessions WHERE id = ?');
  stmt.run(sessionId);

  res.json({ message: 'Logged out successfully' });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Auth server running on http://localhost:${PORT}`);
});
