const BASE_URL = 'http://localhost:3000';

async function signup(email, password) {
  const res = await fetch(`${BASE_URL}/signup`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ email, password })
  });
  const data = await res.json();
  console.log('Signup response:', data);
  return data;
}

async function login(email, password) {
  const res = await fetch(`${BASE_URL}/login`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ email, password })
  });
  const data = await res.json();
  console.log('Login response:', data);
  return data;
}

async function getProfile(sessionToken) {
  const res = await fetch(`${BASE_URL}/profile`, {
    headers: { 'Authorization': `Bearer ${sessionToken}` }
  });
  const data = await res.json();
  console.log('Profile response:', data);
  return data;
}

async function logout(sessionToken) {
  const res = await fetch(`${BASE_URL}/logout`, {
    method: 'POST',
    headers: { 'Authorization': `Bearer ${sessionToken}` }
  });
  const data = await res.json();
  console.log('Logout response:', data);
  return data;
}

// Test workflow
async function test() {
  console.log('=== Testing Auth System ===\n');

  // Signup
  console.log('1. Signing up new user...');
  const signupResult = await signup('user@example.com', 'securepassword123');
  const token = signupResult.sessionToken;

  console.log('\n2. Fetching profile with session...');
  await getProfile(token);

  console.log('\n3. Logging out...');
  await logout(token);

  console.log('\n4. Logging in again...');
  const loginResult = await login('user@example.com', 'securepassword123');
  const newToken = loginResult.sessionToken;

  console.log('\n5. Testing rate limiting (wrong password 5+ times)...');
  for (let i = 0; i < 6; i++) {
    console.log(`Attempt ${i + 1}:`);
    await login('user@example.com', 'wrongpassword');
  }
}

